#!/usr/bin/env python3
"""Snapshot resolved Dart package license texts without local filesystem paths."""
import json
import re
from pathlib import Path
from urllib.parse import unquote, urljoin, urlparse

root = Path(__file__).resolve().parents[1]
config = root / ".dart_tool/package_config.json"
if not config.exists():
    raise SystemExit("Run flutter pub get before updating license notices.")
packages = json.loads(config.read_text())["packages"]
sections = [
    "Resolved Dart package license snapshot\n"
    "Generated by tool/update_license_notices.py after flutter pub get.\n"
    "Includes SDK and development dependencies; not a binary inventory.\n"
    "Original license texts below are preserved.\n"
]
missing = []
flutter_package = next(p for p in packages if p["name"] == "flutter")
flutter_uri = urlparse(urljoin(config.as_uri(), flutter_package["rootUri"]))
sdk = Path(unquote(flutter_uri.path)).parent.parent
for package in sorted(packages, key=lambda p: p["name"]):
    name = package["name"]
    if name in {"openplayx", "openplayx_playback"}:
        continue  # Application-owned code uses the root GPL grant.
    uri = urlparse(urljoin(config.as_uri(), package["rootUri"]))
    if uri.scheme != "file":
        raise SystemExit(f"Unsupported package URI for {name}")
    directory = Path(unquote(uri.path))
    manifest = directory / "pubspec.yaml"
    match = re.search(r"^version:\s*([^\s#]+)", manifest.read_text(), re.M) if manifest.exists() else None
    version = match.group(1) if match else "SDK / unspecified"
    notices = sorted(
        p for p in directory.iterdir()
        if p.is_file() and re.fullmatch(
            r"(?:LICENSE|LICENCE|COPYING|NOTICE)(?:[.-].*)?", p.name, re.I
        )
    )
    # Flutter SDK subpackages share the SDK root license.
    if not notices and directory.is_relative_to(sdk / "packages"):
        sdk_license = sdk / "LICENSE"
        if sdk_license.is_file():
            notices = [sdk_license]
    sections.append(f"\n{'=' * 72}\n{name} ({version})\n{'=' * 72}\n")
    if not notices:
        missing.append(name)
        sections.append("No root license/notice file found; review separately.\n")
    for notice in notices:
        sections.append(f"\n--- {notice.name} ---\n")
        sections.append(notice.read_text())
        sections.append("\n")
output = root / "LICENSES/DART_PACKAGES.txt"
output.parent.mkdir(exist_ok=True)
output.write_text("".join(sections))
print(f"Wrote notices for {len(packages) - 2} resolved packages.")
print("Missing notices: " + (", ".join(missing) or "none"))
